opts := pgx.TxOptions{IsoLevel: pgx.RepeatableRead}
for attempt := 0; attempt < 3; attempt++ {
    err = pgx.BeginTxFunc(ctx, pool, opts, func(tx pgx.Tx) error {
        tx.QueryRow(ctx, readBalance, id).Scan(&balance)
        if balance < amount { return ErrInsufficient }
        _, err := tx.Exec(ctx, writeBalance, balance-amount, id)
        return err
    })
    if !errors.As(err, &pgErr) || pgErr.Code != "40001" {
        return err   // nil, or a failure a retry won't fix
    }
}

